
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_wc04_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_wc04", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.013076845742409e-01, -3.030533424622101e-01, -3.055868770961888e-01, -3.092791736296172e-01, -3.146913282160028e-01, -3.226803277500541e-01, -3.345319930723845e-01, -3.519151629979830e-01, -3.752247095748712e-01, -3.917142360681641e-01, -3.202600846960117e-01, -1.218634355143156e-01, -9.053875470452416e-02, -1.034449100704463e-01, -1.115079615504820e-01, -1.126235250723918e-01, -1.052955350252500e-01, -8.660578227905118e-02, -6.227442575544029e-02, -4.246212652022060e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


